name: CLA Check
on:
  pull_request_target:
    types: [opened, edited, synchronize]

jobs:
  check-cla:
    runs-on: ubuntu-latest
    steps:
      - name: Check for CLA text
        id: cla-check
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prDescription = context.payload.pull_request.body;
            const claText = "By submitting this pull request, I confirm that you can use, modify, copy, and redistribute this contribution, under the terms of your choice.";

            if (!prDescription || !prDescription.includes(claText)) {
              core.setFailed("Pull request description is missing the required CLA text.");

              // Comment on the PR with instructions
              const comment = `:warning: **CLA Verification Required** :warning:\n\nPlease add the following text to your pull request description:\n\n\`\`\`\n${claText}\n\`\`\``;

              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: comment
              });
            }
